fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 3);
        host::display::state_set(3, 77);
    }
    let mut q: i32 = host::display::state_get(1);
    let mut served: i32 = host::display::state_get(2);
    let mut ta: i32 = host::display::state_get(4);
    let mut tb: i32 = host::display::state_get(5);
    if t % 20 == 0 {
        let seed: i32 = host::display::state_get(3) * 1103515245 + 12345;
        host::display::state_set(3, seed);
        if ((seed >> 16) & 4095) % 100 < 55 && q < 22 {
            q = q + 1;
        }
    }
    if ta > 0 {
        ta = ta - 1;
        if ta == 0 { served = served + 1; }
    } else if q > 0 {
        q = q - 1;
        ta = 45;
    }
    let open: bool = host::display::pointer_down() == 1;
    if open {
        if tb > 0 {
            tb = tb - 1;
            if tb == 0 { served = served + 1; }
        } else if q > 0 {
            q = q - 1;
            tb = 45;
        }
    }
    host::display::state_set(1, q);
    host::display::state_set(2, served);
    host::display::state_set(4, ta);
    host::display::state_set(5, tb);
    host::display::clear(0x101014);
    host::display::fill_rect(40, 100, 60, 40, 0x306040);
    if ta > 0 { host::display::fill_rect(50, 70, 16, 20, 0xd0b080); }
    host::display::fill_rect(40, 180, 60, 40, if open { 0x306040 } else { 0x282828 });
    if tb > 0 { host::display::fill_rect(50, 150, 16, 20, 0xd0b080); }
    let mut i: i32 = 0;
    while i < q {
        host::display::fill_rect(130 + i * 15, 110, 10, 18, 0x8090a0);
        i = i + 1;
    }
    host::display::draw_string(40, 30, "SERVED", 0x808080, 2);
    host::display::draw_number(140, 30, served, 0xffffff, 2);
    host::display::draw_string(40, h - 40, "HOLD = OPEN 2ND REGISTER", 0x606060, 1);
    host::display::present();
}
